strncpy(materialName, material.c_str(), MAXLEN-1);
materialName[MAXLEN-1] = 0;
mbi->tag_get_handle("material", MAXLEN, MB_TYPE_OPAQUE, material_tag,
    moab::MB_TAG_SPARSE | moab::MB_TAG_CREAT);
mbi->tag_set_data(material_tag, &handle, 1, materialName);
